SELECT "nct", "author", "year", "pubmed_id", "cancer_type", "treatment_regimen", "ici_name", "ici_class", "therapy_modality", "combination_type", "control_regimen", "control_type", "lines_of_treatment", "clinical_setting_in_relation_to_surgery", "primary_endpoint", "primary_endpoint_is_multiple_or_composite", "secondary_endpoint", "pdl1_inclusion", "other_biomarker_inclusion" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%Breast%' AND "other_biomarker_inclusion" = 'Yes'